#include "base.h"
extern H LoadImageW(H,T,U32,int,int,U32);
extern int GetSystemMetrics(int);
H brandicon(H inst,int small){return LoadImageW(inst,(T)(N)101,1,GetSystemMetrics(small?49:11),GetSystemMetrics(small?50:12),0x8000);}

int getstr(H root,T key,T name,W*out,int cap){U32 bytes=cap*2;out[0]=0;if(RegGetValueW(root,key,name,2,0,out,&bytes)||bytes<2||bytes>(U32)cap*2||out[bytes/2-1]){out[0]=0;return 0;}return 1;}
int putstr(H r,T k,T n,T v){H h=0;if(RegCreateKeyExW(r,k,0,0,0,2,0,&h,0))return 0;U32 e=RegSetValueExW(h,n,0,1,(const U8*)v,(sz(v)+1)*2);RegCloseKey(h);return !e;}
int delstr(H r,T k,T n){H h=0;U32 e=RegOpenKeyExW(r,k,0,2,&h);if(e)return e==2;e=RegDeleteValueW(h,n);RegCloseKey(h);return !e||e==2;}
int loadendpoint(H r,T k,Endpoint*e){W inv[320];memset(e,0,sizeof(*e));return getstr(r,k,L"Pair",inv,CNT(inv))&&pair(inv,e->host,e->ip,e->machine);}
int saveendpoint(H r,T k,const Endpoint*e){W inv[320];return invite(inv,CNT(inv),e->host,e->ip,e->machine)&&putstr(r,k,L"Pair",inv);}
int errnum(W*out,int n,T why,U32 err){_snwprintf(out,n-1,L"%ls (Windows 코드 %u)",why,err);out[n-1]=0;return 0;}
int trusted(void){W path[1024];U32 n=GetModuleFileNameW(0,path,CNT(path));if(!n||n>=CNT(path))return 0;
static const Guid policy={0x00aac56b,0xcd44,0x11d0,{0x8c,0xc2,0,0xc0,0x4f,0xc2,0x95,0xee}};TrustFile f={sizeof(f),path,0,0};TrustData d={0};d.size=sizeof(d);d.ui=2;d.choice=1;d.file=&f;d.action=1;I32 s=WinVerifyTrust(BAD,&policy,&d);d.action=2;WinVerifyTrust(BAD,&policy,&d);return s==0;}
int guidtext(W*out,int cap){Guid g;if(cap<33||CoCreateGuid(&g))return 0;_snwprintf(out,cap,L"%08x%04x%04x%02x%02x%02x%02x%02x%02x%02x%02x",g.a,g.b,g.c,g.d[0],g.d[1],g.d[2],g.d[3],g.d[4],g.d[5],g.d[6],g.d[7]);return sz(out)==32;}
/* Only fixed Windows networking cmdlets call this helper. Input is generated by
   typed builders (IPv4s, GUID profile, interface checks). Never credentials, paths,
   share names or arbitrary input. No scripts on disk, no execution policy switches. */
int cmdlet(T code,W*out,int cap){W sys[520],cmd[6200];out[0]=0;U32 n=GetSystemDirectoryW(sys,CNT(sys));if(!n||n>=CNT(sys)||!cat(sys,CNT(sys),L"\\WindowsPowerShell\\v1.0\\powershell.exe"))return 0;
if(!cp(cmd,CNT(cmd),L"\"")||!cat(cmd,CNT(cmd),sys)||!cat(cmd,CNT(cmd),L"\" -NoLogo -NoProfile -NonInteractive -Command \"$ErrorActionPreference='Stop'; try { ")||!cat(cmd,CNT(cmd),code)||!cat(cmd,CNT(cmd),L" } catch { 'Windows network command failed'; exit 1 }\""))return 0;
Security sa={sizeof(sa),0,1};H rd=0,wr=0,nil=0;Process p={0};Startup st={0};st.n=sizeof(st);st.flags=0x101;
if(!CreatePipe(&rd,&wr,&sa,0))return 0;if(!SetHandleInformation(rd,1,0))goto fail;nil=CreateFileW(L"NUL",0x80000000,3,&sa,3,0,0);if(nil==BAD){nil=0;goto fail;}st.input=nil;st.output=st.error=wr;if(!CreateProcessW(sys,cmd,0,0,1,0x08000000,0,0,&st,&p))goto fail;CloseHandle(wr);wr=0;CloseHandle(nil);nil=0;
char buf[2048];int pos=0;U32 got=0;while(ReadFile(rd,buf,sizeof(buf),&got,0)&&got){for(U32 i=0;i<got;i++)if(pos+1<cap){unsigned char c=buf[i];out[pos++]=(c>=32&&c<127)||c=='\n'||c=='\r'||c=='\t'?c:' ';}}while(pos&&(out[pos-1]=='\n'||out[pos-1]=='\r'||out[pos-1]==' '))pos--;out[pos]=0;U32 status=1;WaitForSingleObject(p.process,0xffffffff);GetExitCodeProcess(p.process,&status);CloseHandle(p.thread);CloseHandle(p.process);CloseHandle(rd);return status==0;
fail:if(rd)CloseHandle(rd);if(wr)CloseHandle(wr);if(nil)CloseHandle(nil);return 0;}
int listip(W*out,int cap){return cmdlet(L"Get-NetIPAddress -AddressFamily IPv4 -AddressState Preferred | Where-Object { $_.InterfaceAlias -ne 'Loopback Pseudo-Interface 1' } | ForEach-Object { $_.IPAddress }",out,cap);}
int islocal(T ip){W buff[800];if(!ipprivate(ip)||!listip(buff,CNT(buff)))return 0;W*p=buff;while(*p){W*q=p;while(*q&&*q!='\n'&&*q!='\r')q++;W c=*q;*q=0;if(eq(p,ip))return 1;if(!c)break;p=q+1;while(*p=='\n'||*p=='\r')p++;}return 0;}
